/** Simple HTML escape (avoids dependency on app.js escapeHtml) */
function _esc(s) { return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }

/** Get textbook reference HTML for a topic */
window.getBookRefsHTML = function(topicId) {
  const refs = window.BOOK_REFS[topicId];
  if (!refs || !refs.books || !refs.books.length) return "";
  return refs.books.map(b =>
    `<div style="margin:4px 0;padding:6px 8px;background:var(--bg1);border-left:3px solid var(--accent);border-radius:0 var(--radius) var(--radius) 0;font-size:0.75rem">
      <b>${_esc(b.title)}</b> · Ch ${_esc(b.chapters)} · p ${_esc(b.pages)}<br>
      <span class="muted">${_esc(b.focus)}</span>
    </div>`
  ).join("");
};
